let RandomIdxs = [1, 0, 0, 101, 0, 0, 1, 0, 101, 0, 1,101, 0, 1, 0, 101];
cc.Class({
    extends: require("BirdNineHeads_Symbol"),

    properties: {
        label:cc.Label
    },

    onLoad () {
        this._super();
        this.label = this.node.getChildByName("label").getComponent(cc.Label);
    },

    //重写
    StartMove: function () {
        this._super();
        this.hideLabel();
    },

    /**
     * @override
     * @param {*} id
     * @param {*} data
     */
    ShowById:function(id,data){
        this._super(id,data);
    },

    /**
     *
     * @constructor
     */
    ShowRandomSymbol() {
        let randIdx = Global.random(1, RandomIdxs.length)
        let randVal = RandomIdxs[randIdx-1]
        this.ShowById(randVal);
    },

    /**
     * 播放吃香蕉动画
     */
    async playEatBanana(coin) {
        let id = this._id
        if(this._showNode){
            this._showNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg();
        this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
        this._showNode.active = true
        let spine = this._showNode.getComponent(sp.Skeleton);
        spine.setAnimation(0, "chixiangjiao", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            this.showLabel(coin);
        })
        await SlotsFacade.delayTime(1.5);
    },

    showLabel(coin) {
        coin = coin || 0;
        if(coin < 1) {
            this.hideLabel();
            return;
        }
        this.label.string = Global.convertNumToShort(coin);
        this.label.node.active = true;
    },

    hideLabel() {
        this.label.node.active = false;
    }
});
