/**
 * 奖励类型
 * @type {{Coin: number, Jackpot: number, Banana: number}}
 */
let BonusItemType = {
    Jackpot:1,  // 香蕉带jackpot
    Coin:2,     // 金币图标
    Banana:3,   // 香蕉带金币
}

/**
 * 主场景资源
 */
cc.Class({
    extends: cc.Component,

    properties:{
        panel:cc.Node,
        remaining_tips:cc.Node,
        reels_node:cc.Node,
        top_ani:cc.Node,
        banana_node:cc.Node,
        start_drop_game:cc.Node,
        coin_item_template:cc.Node,
        bnana_item_template:cc.Node,

        _bananaItems:[], // 奖励列表
        _reels:[],   // 所有卷轴
        _data:null,
        _callBack:null,
        _symbolTemplate:null,   //符号节点
    },

    onLoad() {
        this._symbolTemplate = cc.vv.gameData.GetPrefabByName(SlotsFacade.dm.getGameCfg().symbolPrefab);
        this._symbolTemplate.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE;
        this._initData();
        this._initReels();
    },

    /**
     * 初始化数据
     */
    _initData() {
        this._data = {
            stoppedReelCnt:0,   // 已经停止的列数量
            respData:null,      // 请求响应数据
        };
    },

    /**
     * 初始化卷轴
     */
    _initReels() {
        this._reels = [];
        for(let i=0; i<3; i++) {
            let cmp = cc.find(`reel${i+1}`, this.reels_node).addComponent("BirdNineHeads_BigReel");
            cmp.Init(i, 1, this.top_ani);
            cmp.setHandler(this._onReelChange.bind(this));
            this._reels.push(cmp);
        }
    },

    /**
     * 卷轴事件处理
     * @param {*} evt
     */
    _onReelChange(evt) {
        if(evt.evtName == "reel_spin_end") {
            SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_reel_stop");
            this._data.stoppedReelCnt++;
            let reelIdx = evt.data;
            let wildIds = SlotsFacade.dm.getGameCfg().wildIds;
            let symbol = this._reels[reelIdx].GetSymbolByRow(0);
            if(wildIds.includes(symbol.GetShowId())) {
                SlotsFacade.soundMgr.playEffect("symbol_bonus");
            }
            if(this._data.stoppedReelCnt == 3) {
                this.spinEnd();
            }
        }
    },

    /**
     * 初始化ui
     * @param {*} isReconnect
     */
    _initView() {
        let bonusGame = SlotsFacade.dm.bonusGame;
        this.remaining_tips.active = true;
        this.showRestCnt(bonusGame.spinCnt, true);

        // 显示上方香蕉列表
        this._bananaItems = [];
        for(let i=0; i<3; i++) {
            let colNode = this.banana_node.getChildByName(`col${i+1}`);
            colNode.removeAllChildren();
            let itemsData = bonusGame.items[i];
            let arr = [];
            for(let j=itemsData.length-1; j>=0; j--) {
                let itemInfo = itemsData[j];
                let item = null;
                if(itemInfo.type == BonusItemType.Jackpot) {
                    item = cc.instantiate(this.bnana_item_template);
                    item.active = true;
                    item.parent = colNode;
                    let imgCmp = item.getChildByName("icon").getComponent("ImgSwitchCmp");
                    imgCmp.node.active = true;
                    imgCmp.setIndex({"4":2, "3":1, "1":0}[itemInfo.jackpotId.toString()]);
                }if(itemInfo.type == BonusItemType.Coin) {
                    item = cc.instantiate(this.coin_item_template);
                    item.active = true;
                    item.parent = colNode;
                }if(itemInfo.type == BonusItemType.Banana) {
                    item = cc.instantiate(this.bnana_item_template);
                    item.active = true;
                    item.parent = colNode;
                    let label = item.getChildByName("label").getComponent(cc.Label);
                    label.node.active = true;
                    label.string = Global.convertNumToShort(itemInfo.mult * bonusGame.startPrize);
                }
                if(arr.length>0) {
                    item.y = item.height/2 + arr[0].y + arr[0].height/2;
                }else {
                    item.y = item.height/2;
                }
                arr.unshift(item);
            }
            this._bananaItems.push(arr);
        }

        // 显示图标
        for(let i=0; i<this._reels.length; i++) {
            let item = this._reels[i];
            let symbol = item.getFirstSymbol();
            symbol.StartMove();
            symbol.ShowRandomSymbol();
        }
    },

    /**
     * 设置剩余次数
     * @param {*} cnt
     * @param {*} isInit
     */
    showRestCnt(cnt, isInit) {
        let label = this.remaining_tips.getChildByName("label").getComponent(cc.Label);
        label.string = cnt.toString();
    },

    /**
     * 开始旋转
     */
    startMove() {
        this._data.stoppedReelCnt = 0;
        this._canMoveReels = [];
        for(let i=0; i<this._reels.length; i++) {
            let item = this._reels[i];
            item.StartMove();
            this._canMoveReels.push(item);
        }
    },

    /**
     * 收到respin消息
     * @param {*} msg
     */
    async onRecSpinData(msg) {
        this._data.respData = msg.data;
        SlotsFacade.dm.bonusGame = msg.data.bonusGame;
        await SlotsFacade.delayTime(1);
        // 设置结果
        this.setSlotsResult();
        // 设置列停止间隔
        let reelStopInterv = 0.2;
        for(let i = 0; i < this._canMoveReels.length; i++){
            let item = this._canMoveReels[i];
            let idx = item.GetReelIdx();
            item.StopMove(idx * reelStopInterv);
        }
    },

    /**
     * 设置卷轴结果
     */
    setSlotsResult() {
        let cards = this._data.respData.result.cards;
        for(let i=0; i<this._canMoveReels.length; i++) {
            let item = this._canMoveReels[i];
            item.SetResult([{sid:cards[i]}]);
        }
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        this.showRestCnt(SlotsFacade.dm.bonusGame.spinCnt);
        await SlotsFacade.delayTime(0.5);
        await this.settlementARound();
        if(!SlotsFacade.dm.bonusGame.isEnd && SlotsFacade.dm.bonusGame.spinCnt > 0) {
            // todo recover
            this.run();
        }else {
            this.totalSettlement();
        }
    },

    /**
     * 开始新一轮运行
     */
    async run() {
        this._currRoundBonus = [];
        let bonusGame = SlotsFacade.dm.bonusGame;
        // 更新次数
        this.showRestCnt(bonusGame.spinCnt-1);
        // 开始转动
        this.startMove();
        // 请求消息
        // todo recover
        SlotsFacade.dm.reqSubGame({rtype:1});
    },

    /**
     * 进入游戏
     * @param {*} callBack
     * @param {*} isReconnect
     * @param {*} initBonusInfo bonusIdxs
     */
    async enterGame(callBack, isReconnect) {
        this._callBack = callBack;

        if(!isReconnect) {
            // 显示开始弹窗
            this.start_drop_game.active = true;
            this.start_drop_game.scale = 0;
            // SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_superfreespin_rensheng");
            cc.tween(this.start_drop_game)
                .to(0.5, {scale:1.5}, {easing:"backOut"})
                .delay(1)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    this.start_drop_game.active = false;
                })
                .start();
            await SlotsFacade.delayTime(2);
            // 转场动画
            await SlotsFacade.mainPanel.showSceneTransition();
        }
        SlotsFacade.soundMgr.playBgm("music_JungleKingpin_BonusBg");
        SlotsFacade.prizePool.alignTop();
        SlotsFacade.mainPanel.showBg(1);
        SlotsFacade.mainPanel.slots.active = false;
        this.panel.active = true;
        this.banana_node.active = true;
        this._initData();
        this._initView(isReconnect);
        await SlotsFacade.delayTime(1.5);
        // todo recover
        this.run();
    },

    /**
     * 退出游戏
     */
    async exitGame(coin) {
        await SlotsFacade.mainPanel.showSceneTransition();
        SlotsFacade.prizePool.toNormal();
        SlotsFacade.mainPanel.showBg(0);
        SlotsFacade.mainPanel.slots.active = true;
        this.panel.active = false;
        this.banana_node.active = false;
        if(this._callBack) {
            this._callBack(coin);
        }
    },


    /**
     * 结算一轮
     * @returns {Promise<void>}
     */
    async settlementARound() {
        let result = this._data.respData.result;
        // 随机金币
        let randomPromiseArr = [];
        for(let i=0; i<result.cards.length; i++) {
            let card = result.cards[i];
            if(card > 0) {
                // 播放猴子动画
                let symbol = this._reels[i].getFirstSymbol();
                symbol.playidleAnimation();
                if(card == SlotsFacade.dm.getGameCfg().bonusId) {
                    randomPromiseArr.push(this._randomEffect(i, result.items[i].id));
                }
            }
        }
        if(randomPromiseArr.length) {
            await Promise.all(randomPromiseArr);
            SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_bonus_paomadeng_over");
        }
        await SlotsFacade.delayTime(0.5);
        // 金币掉落
        let promiseArr = [];
        for(let i=0; i<result.cards.length; i++) {
            let card = result.cards[i];
            if(card < 1) {
                continue;
            }
            promiseArr.push(this._dropGold(i, result.items[i]));
        }
        await Promise.all(promiseArr);

        // 设置金币
        try {
            let nTotal = 0;
            if(cc.vv.gameData._gameInfo) {
                nTotal = cc.vv.gameData.GetGameWin();
            }
            if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
                nTotal = cc.vv.gameData.GetGameTotalFreeWin();
            }
            SlotsFacade.bottomCmp.SetWin(nTotal + SlotsFacade.dm.bonusGame.winCoin);
        }catch (e) {
            console.log(e);
        }
    },

    /**
     * 随机金币动画
     * @param colIdx
     * @param coinIdx
     * @returns {Promise<void>}
     * @private
     */
    async _randomEffect(colIdx, coinIdx) {
        let itemArr = this._bananaItems[colIdx];
        let ascRoad = [];
        for(let i=0; i<itemArr.length; i++) {
            ascRoad.push(i);
        }
        let desRoad = ascRoad.concat().reverse();
        ascRoad.pop();
        desRoad.pop();
        let road = ascRoad.concat(desRoad); // 路径
        let minStep = 10;
        let stepArr = [];
        let currStep = 0;
        let len = minStep+road.length;
        // 生成步数
        for(let j=0; j<len; j++) {
            stepArr.push(itemArr[road[currStep]]);
            if(j>=minStep && road[currStep] == coinIdx-1) {
                break;
            }
            currStep += 1;
            if(currStep >= road.length) {
                currStep = 0;
            }
        }
        let totalTime = 3;
        // 播放动画
        for(let i=0; i<stepArr.length; i++) {
            let light = stepArr[i].getChildByName("light");
            light.active = true;
            light.opacity = 0;
            cc.tween(light)
                .delay(this._genDelayTime(totalTime, stepArr.length, i+1))
                .call(()=>{
                    SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_bonus_paomadeng");
                })
                .to(0.1, {opacity:0xff})
                .to(0.1, {opacity:0})
                .start();
        }
        await SlotsFacade.delayTime(totalTime);
    },

    /**
     * 生成随机动画时间 (用三角形面积差)
     * @param totalTime
     * @param step
     * @param currStep
     * @private
     */
    _genDelayTime(totalTime, step, currStep) {
        let tan = 1.73205080757; //tan 60度的值
        let stepLen = Math.sqrt(2*totalTime/tan);// 边长
        let unitLen = stepLen/step;
        // let sPre = 0;   // 上一个三角形面积
        let sCurr = 0;  // 当前三角形面积
        // if(currStep>1) {
        //     sPre = 1/2 * unitLen*(currStep-1) * unitLen*(currStep-1)*tan;
        // }
        sCurr = 1/2 * unitLen*currStep * unitLen*currStep*tan;
        // return sCurr - sPre;
        return sCurr;
    },

    /**
     * 掉落金币
     * @param colIdx 列
     * @param data
     * @returns {Promise<void>}
     * @private
     */
    async _dropGold(colIdx, data) {
        let coinItem = this._bananaItems[colIdx].splice(data.id-1, 1)[0];
        let symbol = this._reels[colIdx].getFirstSymbol();

        // 金币掉落动画
        let itemGlobalPos = coinItem.convertToWorldSpaceAR(cc.v2(0,0));
        coinItem.parent = this.top_ani;
        coinItem.setPosition(this.top_ani.convertToNodeSpaceAR(itemGlobalPos));
        let endPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
        endPos = this.top_ani.convertToNodeSpaceAR(endPos);
        cc.tween(coinItem)
            .to(0.5, {x:endPos.x, y:endPos.y})
            .start();

        // 金币列表位置调整
        let coinItemArr = this._bananaItems[colIdx];
        let refY = 0;
        for(let i=coinItemArr.length-1; i>=0; i--) {
            let endY = coinItemArr[i].height/2;
            if(i<coinItemArr.length-1) {
                endY += refY;
            }
            refY = endY + coinItemArr[i].height/2;
            cc.tween(coinItemArr[i])
                .to(0.5, {y:endY})
                .start();
        }

        await SlotsFacade.delayTime(0.5);
        SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_wild_eat");
        let coin = 0;
        if(data.coin) {
            coin = data.coin;
        }else if(data.jackpot) {
            coin = data.jackpot.value;
            await SlotsFacade.popup.showWinJPGold(data.jackpot.id, coin);
        }
        coinItem.removeFromParent();
        await symbol.playEatBanana(coin);
    },

    /**
     * 总结算
     * @returns {Promise<void>}
     */
    async totalSettlement() {
        let winCoin = SlotsFacade.dm.bonusGame.winCoin;
        await SlotsFacade.popup.showWinDropGameGold(winCoin);
        this.exitGame(winCoin);
    },
})