/**
 * 游戏流辅助类
 */
cc.Class({
    extends: cc.Component,

    /**
     * 进入房间
     */
    async enterRoom() {
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            SlotsFacade.bottomCmp.SetWin(nTotal);
            await this.enterFreeGame(true);
        }
        if(SlotsFacade.dm.bonusGame) {
            await this.enterDropGame(true);
        }
        SlotsFacade.slots.CanDoNextRound();
    },

    /**
     * 开始移动
     */
    async startMove() {
        SlotsFacade.wildGame.startMove();
    },

    /**
     * 收到spin消息
     * @param {*} msg
     */
    async onSpinMsg(msg) {
        await SlotsFacade.wildGame.onSpinMsg();
        SlotsFacade.slots._gameInfo = msg;
        let cards = msg.resultCards;
        SlotsFacade.slots.SetSlotsResult(cards);
        SlotsFacade.slots.SetReelStateInfo(cards);
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        cc.vv.AudioManager.stopEffectByName("sound_JungleKingpin_reel_run");
        await SlotsFacade.wildGame.spinEnd();
        // 显示中奖路线
        SlotsFacade.slots.ShowWinTrace();
        // 更新金币
        let nWin = cc.vv.gameData.GetGameWin();
        let shatterWinCoin = 0;
        if(SlotsFacade.dm.getSpinData().shatterInfo) {
            shatterWinCoin = SlotsFacade.dm.getSpinData().shatterInfo.winCoin;
        }
        nWin -= shatterWinCoin;
        let nTotal = nWin;
        let updateTotal = true;
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin();
            nTotal -= shatterWinCoin;
            updateTotal = false;
        }
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal, updateTotal, res);
        });
        // 消除symbol
        await this.eraseSymbol();

        await this.enterDropGame();

        // await SlotsFacade.delayTime(0.5);
        // 控制按钮
        if (SlotsFacade.dm.isTriggerFree()) {
            if(SlotsFacade.dm.isFistTriggerFree()) {
                await this.enterFreeGame();
            }else {
                await SlotsFacade.popup.showWinFreeCnt(SlotsFacade.dm.triggerFreeCnt(), false);
            }
        } else if (SlotsFacade.dm.isLastEndFree()) {
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            await SlotsFacade.popup.showWinFreeGold(SlotsFacade.dm.getFreeWinCoin(), SlotsFacade.dm.GetTotalFree());
            await SlotsFacade.mainPanel.showSceneTransition();
            SlotsFacade.slots.startMoveAllSymbol();
            SlotsFacade.slots.Resume();
            await this.enterNormalGame();
        }
        SlotsFacade.slots.CanDoNextRound();
    },

    /**
     * 进入免费游戏
     */
    async enterFreeGame(isReconnect) {
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        if(!isReconnect) {
            SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_scatter_start");
            await SlotsFacade.slots.playTriggerAni(SlotsFacade.dm.getSpinData().scatterZJLuXian.indexs);
            SlotsFacade.slots.Backup();
            await SlotsFacade.collect.addStep();
            if(SlotsFacade.dm.bonusTrail.count == SlotsFacade.dm.bonusTrail.totalCount) {
                await SlotsFacade.collect.triggerSuperGame();
                await SlotsFacade.popup.showWinSuperFreeCnt(SlotsFacade.dm.triggerFreeCnt());
            }else {
                await SlotsFacade.popup.showWinFreeCnt(SlotsFacade.dm.triggerFreeCnt(), true);
            }
            await SlotsFacade.mainPanel.showSceneTransition();
        }
        SlotsFacade.mainPanel.showBg(1);
        // SlotsFacade.character.toFreeState();
        SlotsFacade.soundMgr.playFreeBgm();
        let total = cc.vv.gameData.GetTotalFree();
        let rest = cc.vv.gameData.GetFreeTime();
        SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total);
        SlotsFacade.collect.hide();
        SlotsFacade.slots.showFreeTitle(true, SlotsFacade.dm.bonusTrail.state > 0?1:0);
        SlotsFacade.slots.changeReelsBg(true);
        await SlotsFacade.delayTime(0.5);
        if(SlotsFacade.dm.bonusTrail.state > 0) {
            await SlotsFacade.wildGame.enterWildGame(isReconnect);
        }
    },

    /**
     * 进入普通游戏
     */
    async enterNormalGame() {
        SlotsFacade.collect.show();
        SlotsFacade.bottomCmp.ShowFreeModel(false);
        SlotsFacade.mainPanel.showBg(0);
        SlotsFacade.character.toNormalState();
        Global.SlotsSoundMgr.playNormalBgm(true);
        SlotsFacade.wildGame.exitWildGame();
        SlotsFacade.collect.show();
        SlotsFacade.slots.showFreeTitle(false);
        SlotsFacade.slots.changeReelsBg(false);
        if(SlotsFacade.dm.isLastEndFree()) {
            let nTotal = cc.vv.gameData.GetGameTotalFreeWin()
            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(nTotal, nTotal,true, res);
            });
        }
    },

    /**
     * 进入drop game
     */
    async enterDropGame(isReconnect) {
        if(!SlotsFacade.dm.bonusGame) {
            return;
        }
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        if(!isReconnect) {
            SlotsFacade.slots.startMoveAllSymbol();
            let bonusIdxs = SlotsFacade.dm.getBonusIdxs();
            await SlotsFacade.slots.playTriggerAni(bonusIdxs);
        }
        let coin = await new Promise(res=>{
            SlotsFacade.dropGame.enterGame(res, isReconnect);
        });
        SlotsFacade.dm.AddCoin(coin);
        // 更新金币
        let nWin = coin;
        let nTotal = coin;
        if(cc.vv.gameData._gameInfo) {
            nTotal = cc.vv.gameData.GetGameWin();
        }
        let updateTotal = true;
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin();
            updateTotal = false;
        }
        nTotal += coin;
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,updateTotal, res);
        });
    },

    /**
     * 消除配饰symbol
     * @returns {Promise<void>}
     */
    async eraseSymbol() {
        let shatterInfo = SlotsFacade.dm.getSpinData().shatterInfo;
        if(!shatterInfo) {
            return;
        }
        SlotsFacade.slots.startMoveAllSymbol();
        let cfg = SlotsFacade.dm.getGameCfg();
        let hasShatter = false;
        while(true) {
            try {
                //找出bonus symbol
                let bonusSymbols = [];
                let reels = SlotsFacade.slots._reels;
                for(let i=0; i<reels.length; i++) {
                    let symbols = reels[i]._symbols;
                    for(let j=0; j<symbols.length-1; j++) {
                        if(cfg.bonusId == symbols[j].GetShowId()) {
                            bonusSymbols.push(symbols[j]);
                        }
                    }
                }
                if(!hasShatter) {
                    hasShatter = true;
                    // 播放吼叫动画
                    for(let s of bonusSymbols) {
                        s.playShatterAni();
                    }
                    SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_goldwild_hou");
                    await SlotsFacade.delayTime(1);
                }
                let reelState = [0,0,0,0,0];
                let isRemove = false;
                // 消除
                for(let i=0; i<reels.length; i++) {
                    reelState[i] = reels[i].eraseSymbol();
                    if(reelState[i] > 0) {
                        isRemove = true;
                    }
                }
                SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_symbol_sui");
                await SlotsFacade.delayTime(1);
                // 填充
                for(let i=0; i<reels.length; i++) {
                    let cnt = reelState[i];
                    if(cnt > 0) {
                        if(cnt > shatterInfo.extraCards[i].length) {
                            break;
                        }
                        reels[i].fillSymbols(shatterInfo.extraCards[i].splice(0, cnt));
                    }
                }
                SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_symbol_drop");
                await SlotsFacade.delayTime(0.4);
                if(!isRemove) {
                    break;
                }
                let hasRest = false;
                for(let i of shatterInfo.extraCards) {
                    if(i.length > 0) {
                        hasRest = true;
                    }
                }
                if(!hasRest) {
                    break;
                }
            }catch (e) {
                console.log(e);
                break;
            }
        }

        // 显示中奖路线
        SlotsFacade.slots._gameInfo.zjLuXian = shatterInfo.zjLuXian;
        SlotsFacade.slots._gameInfo.scatterZJLuXian = shatterInfo.scatterResult;
        SlotsFacade.slots.ShowWinTrace();
        // 更新金币
        let nWin = shatterInfo.winCoin;
        let nTotal = cc.vv.gameData.GetGameWin();
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
        });
    }
 })