
/**
 * 收集进度
 */
cc.Class({
    extends: cc.Component,

    properties: {
        progress:cc.Node,
		items:[cc.Node],
		title:cc.Node,
		tips_btn:cc.Button,
		tips:cc.Node,

		_step:0,
		_topZIndex:100,
    },

    onLoad() {
		this.tips.active = false;
		this.tips_btn.node.on("click", ()=>{
			this._showTips();
		}, this);
    },

    start() {
		this._step = SlotsFacade.dm.bonusTrail.count;
		this.setStep(this._step);
    },

	/**
	 * 显示super free game 说明提示
	 */
	_showTips() {
		if(this.tips.active) {
			return;
		}
		this.tips.active = true;
		this.tips.opacity = 0;
		cc.tween(this.tips)
			.to(0.5, { opacity: 0xff })
			.delay(2)
			.to(0.5, {opacity:0})
			.call(()=>{
				this.tips.active = false;
			})
			.start();
	},

	/**
	 * 添加步数
	 */
	async addStep() {
		SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_collect");
		this._topZIndex++;
		let item = this.items[this._step];
		item.zIndex = this._topZIndex;
		// icon 动画
		let icon = item.getChildByName("icon");
		icon.getComponent("ImgSwitchCmp").setIndex(1);
		cc.tween(icon)
			.to(0.3, {scale:1.5})
			.to(0.2, {scale: 1})
			.start();
		await SlotsFacade.delayTime(0.5);

		// icon背景动画
		let ani = item.getChildByName("ani");
		ani.active = true;
		let aniCmp = ani.getComponent(cc.Animation);
		aniCmp.play();
		await new Promise(res=>{
			aniCmp.on("finished", ()=>{
				ani.active =false;
				aniCmp.off("finished");
				res();
			}, this);
		})
		this._step += 1;
	},

	/**
	 * 设置步数
	 */
	setStep(step) {
		this._step = step;
		for(let i=0; i<this.items.length; i++) {
			let item = this.items[i];
			item.getChildByName("ani").active = false;
			item.getChildByName("light").active = false;
			let icon = item.getChildByName("icon");
			icon.getComponent("ImgSwitchCmp").setIndex(step>i?1:0);
		}
	},

	/**
	 * 播放触发super free game 动画
	 * @returns {Promise<void>}
	 */
	async triggerSuperGame() {
		SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_superfreespin_shan");
		// 播放item 闪光动画
		for(let item of this.items) {
			let light  = item.getChildByName("light");
			light.active = true;
			light.scale = 0;
			light.angle = 0;
			cc.tween(light)
				.parallel(
					cc.tween().to(0.25, {scale:1}),
					cc.tween().to(0.25, {angle:180})
				)
				.parallel(
					cc.tween().to(0.25, {scale:0}),
					cc.tween().to(0.25, {angle:360})
				)
				.parallel(
					cc.tween().to(0.25, {scale:1}),
					cc.tween().to(0.25, {angle:540})
				)
				.parallel(
					cc.tween().to(0.25, {scale:0}),
					cc.tween().to(0.25, {angle:720})
				)
				.call(()=>{
					light.active = false;
				})
				.start();
		}

		// 播放title动画
		cc.tween(this.title)
			.to(0.25, {scale:1.2})
			.to(0.25, {scale:1})
			.to(0.25, {scale:1.2})
			.to(0.25, {scale:1})
			.start();

		await SlotsFacade.delayTime(1);
	},

	/**
	 * 设置super game 信息按钮状态
	 */
	enableTipsBtn(boo) {
		this.tips_btn.interactable = boo;
	},

    hide() {
        this.node.active = false;
    },

    show() {
		this.setStep(SlotsFacade.dm.bonusTrail.count);
        this.node.active = true;
    }
});
