/**
 * 金刚卷轴
 */
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    /**
     * @override 显示加速
     * @param bShow
     * @param name
     * @constructor
     */
    ShowAntiEffect:function(bShow,name){
        if (bShow == false) {
            if (this._cfg.reelStateInfo) {
                for (let info of this._cfg.reelStateInfo) {
                    let node = cc.find(info.antiNode,this.node)
                    if(node && node.active){
                        node.active = false
                        // 既然不是循环的播放，就不需要主动停止
                        // 点立即停止的时候需要停止加速音效
                        if(this._stopRightNow){
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }

                    }
                }
            }
        }else{
            let node = cc.find(name,this.node)
            if(node){
                node.active = bShow
            }
            else{
                cc.log("未找到加速节点：node_anti");
            }
        }
    },

    /**
     * 消除 symbol
     */
    eraseSymbol() {
        let removeCnt = 0;
        let canEraseSymbols = SlotsFacade.dm.getGameCfg().canEraseSymbols;
        for(let i=0; i<this._symbols.length-1; i++) {
            let symbol = this._symbols[i];
            if(canEraseSymbols.includes(symbol.GetShowId())) {
                this._symbols.splice(i, 1);
                symbol.playBurstAni();
                i--;
                cc.tween(symbol.node)
                    .delay(1)
                    .call(()=>{
                        this._destroySymbol(symbol);
                    })
                    .start();
                removeCnt++;
            }
        }
        return removeCnt;
    },

    /**
     * 填充symbol
     * @param ids
     * @returns {Promise<void>}
     */
    fillSymbols(ids) {
        if(ids.length < 1) {
            return;
        }
        for(let i=0; i<this._symbols.length; i++) {
            this._symbols[i].SetSymbolIdx(i);
        }
        // 填充
        for(let i=0; i<ids.length; i++) {
            let node = cc.instantiate(this._symbolTemplete)
            node.parent = this._holderNode;
            node.setPosition(this.GetSymbolPosByRow(3+i));
            let scp = node.addComponent(this._cfg.scripts.Symbols);
            scp.SetSymbolReelIdx(this._reelIdx);
            scp.Init(this._symbols.length-1,this._topAniNode);
            scp.ShowById(ids[i]);
            this._symbols.splice(this._symbols.length-1,0,scp);
        }
        // 移动
        for(let i=0; i<this._symbols.length-1; i++) {
            let symbol = this._symbols[i];
            symbol.ShowNormal();
            let endPos = this.GetSymbolPosByRow(i);
            cc.tween(symbol.node)
                .to(0.35, {y:endPos.y})
                .start();
        }
    }
});
