cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
    },

    onLoad () {

    },

    //重写
    StartMove: function () {
        this._super();
    },

    /**
     * @override
     * @param {*} id
     * @param {*} data
     */
    ShowById:function(id,data){
        this._super(id,data);
    },

    /**
     * 移动到最低点
     * @override
     * @constructor
     */
    StopMoveDeep() {
        if(!SlotsFacade.dm.getSpinData()) {
            return;
        }
        if(this.GetShowId() == SlotsFacade.dm.getGameCfg().bonusId) {
            SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_goldwild_ground");
        }
    },

    /**
     * @override
     */
    StopMoveEnd() {
        // 播放idle动画
        // let NeedIdleIds = SlotsFacade.dm.getGameCfg().NeedIdleIds;
        // if(NeedIdleIds.includes(this._id)) {
        //     let rewardIdxs = SlotsFacade.dm.getSpinData().rewardIdxs;
        //     if(!rewardIdxs.includes(this._data.idx)) {
        //         this.playidleAnimation();
        //     }
        // }
    },

    //赢钱动画
    playWinAnimation(){
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            this._state = "win";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true);
            this.hideChild(aniNode);
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            let aniCfg = cfg.symbol[id].win_ani;
            if(aniCfg && aniCfg.name != ""){
                aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                if(aniCfg.type == "animation") {
                    let ani = topShowNode.getChildByName(aniCfg.name).getComponent(cc.Animation);
                    ani.node.active = true;
                    ani.play();
                }else {
                    let nodeSp = topShowNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0, aniCfg.name,true)
                    }
                }
            }
        }
        else{
            //如果没有中奖动画，先显示出来
            //TODO：后续补充一个没有spin动画的显示效果
            this._showNode.active = true
            this.playWinTweenAction()
        }
    },

    /**
     * @override
     */
    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true
            let aniNode = this._showNode;
            this.hideChild(aniNode);
            let aniCfg = cfg.symbol[id].stop_ani;
            if(aniCfg.name != ""){
                this.node.zIndex = aniCfg.zIndex - this._symbolIdx + this._reelIdx*10;
                if(aniCfg.type == "animation") {
                    let stopAni = aniNode.getChildByName(aniCfg.name).getComponent(cc.Animation);
                    stopAni.node.active = true;
                    stopAni.play();
                }else {
                    let nodeSp = aniNode.getComponent(sp.Skeleton);
                    if(nodeSp){
                        nodeSp.setAnimation(0, aniCfg.name, false);
                    }
                }
            }
        }
    },

    /**
     * @override
     * @returns {boolean}
     */
    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false;
            }
            let aniNode = this.setAnimationToTop(true);
            aniNode.active = true;
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode);
            topShowNode.active = true;
            this.hideChild(topShowNode);
            let aniCfg = cfg.symbol[id].trigger_ani;
            if(aniCfg.name != ""){
                aniNode.zIndex = aniCfg.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                if(aniCfg.type == "animation") {
                    let stopAni = topShowNode.getChildByName(aniCfg.name).getComponent(cc.Animation);
                    stopAni.node.active = true;
                    stopAni.play();
                }else {
                    let nodeSp = topShowNode.getComponent(sp.Skeleton);
                    if(nodeSp){
                        nodeSp.setAnimation(0, aniCfg.name, aniCfg.loop);
                    }
                }
            }
        }
        return isPlay;
    },

    /**
     * scatter 图标不显示中奖框
     * @override
     */
    ShowKuang(boo) {
        if(this._id == SlotsFacade.dm.getGameCfg().scatterId) {
            boo = false;
        }
        this._super(boo);
    },

    /**
     * 吼叫动画
     */
    playShatterAni() {
        let id = this._id
        if(this._showNode){
            this._showNode.active = false
        }
        let symbolCfg = cc.vv.gameData.getGameCfg().symbol[id];
        let aniNode = this.setAnimationToTop(true);
        aniNode.active = true;
        aniNode.zIndex = symbolCfg.shatter_ani.zIndex - this._symbolIdx + this._reelIdx*10;
        this._showNode = cc.find(symbolCfg.win_node, aniNode);
        this._showNode.active = true
        let topShowNode = this._showNode;
        topShowNode.active = true;
        let spine = topShowNode.getComponent(sp.Skeleton);
        spine.setAnimation(0, symbolCfg.shatter_ani.name, false);
    },

    /**
     * 播放图标爆炸动画
     */
    playBurstAni() {
        let id = this._id
        if(this._showNode){
            this._showNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg();
        this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
        this.hideChild(this._showNode);
        this._showNode.active = true
        let aniNode = this._showNode;
        let aniCfg = cfg.symbol[id].burst_ani;
        aniNode.zIndex = aniCfg.zIndex - this._symbolIdx + this._reelIdx*10;
        if(aniCfg.type == "animation") {
            let ani = aniNode.getChildByName(aniCfg.name).getComponent(cc.Animation);
            ani.node.active = true;
            ani.play();
        }else {
            let nodeSp = aniNode.getComponent(sp.Skeleton);
            if(nodeSp){
                nodeSp.setAnimation(0, aniCfg.name, aniCfg.loop);
            }
        }
    },

    hideChild(node) {
        let children = node.children;
        for(let c of children) {
            c.active = false;
        }
    },

    /**
     * @override
     */
    stopWinTweenAction() {
        //
    }
});
