cc.Class({
    extends: cc.Component,

    properties:{
        wild_node:cc.Node,
        symbolNode:cc.Node,
        symbolSpine:sp.Skeleton,
        symbolLight:cc.Node,
        symbolKuang:cc.Node,
        _isEnterWild:false, // 是否进入了wild游戏
    },

    onLoad() {
        this.wild_node.active = false;
    },

    start() {
        let pos = SlotsFacade.slots.getIdxGlobalPos(13);
        pos = this.wild_node.convertToNodeSpaceAR(pos);
        this.symbolNode.setPosition(pos);
    },

    /**
     * 进入wild game
     * @param isReconnect
     * @returns {Promise<void>}
     */
    async enterWildGame(isReconnect) {
        this._isEnterWild = true;
        this.showWild();
        this.symbolNode.active = true;
        if(isReconnect) {
            this.symbolSpine.setAnimation(0, "idleframe", false);
            this.symbolLight.getComponent(cc.Animation).play();
            this.symbolKuang.active = false;
        }else {
            SlotsFacade.soundMgr.playEffect("sound_JungleKingpin_superfreespin_addwild");
            this.symbolSpine.setAnimation(0, "buling2", false);
            this.symbolSpine.addAnimation(0, "haojiao", false);
            await SlotsFacade.delayTime(0.5);
            this.symbolKuang.active = true;
            let animation = this.symbolKuang.getComponent(cc.Animation);
            animation.on("finished", ()=>{
                this.symbolKuang.active = false;
                this.symbolLight.active = true;
                this.symbolLight.getComponent(cc.Animation).play();
            }, this);
            animation.play();
        }
    },

    /**
     * 退出wild game
     * @returns {Promise<void>}
     */
    async exitWildGame() {
        this._isEnterWild = false;
        this.symbolNode.active = false;
        this.hideWild();
    },

    /**
     * 隐藏wild
     */
    hideWild() {
        this.wild_node.active = false;
    },

    showWild() {
        this.wild_node.active = true;
    },

    /**
     * 开始旋转 还未请求到当局数据
     * @returns {Promise<void>}
     */
    async startMove() {
        let bonusTrail = SlotsFacade.dm.bonusTrail;
        if(bonusTrail.state < 1) {
            return false;
        }
        if(!this._isEnterWild) {
            return;
        }
        this.showWild();
    },

    /**
     * 收到消息
     * @returns {Promise<void>}
     */
    async onSpinMsg() {
        let bonusTrail = SlotsFacade.dm.bonusTrail;
        // 不在大关直接返回
        if(bonusTrail.state < 1) {
            return;
        }
        if(!this._isEnterWild) {
            return;
        }
    },

    /**
     * 旋转结束
     * @returns {Promise<void>}
     */
    async spinEnd() {
        let bonusTrail = SlotsFacade.dm.bonusTrail;
        // 不在大关直接返回
        if(bonusTrail.state < 1 && !this._isEnterWild) {
            return;
        }
        if(!this._isEnterWild) {
            return;
        }
        await this.hideWild();
    }
 })