
/**
 * 金刚卷轴slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
    },

    onLoad() {
        this._super();
    },

    //重写
    StartMove: function () {
        this._super()
        SlotsFacade.flowCtrl.startMove();
        if(SlotsFacade.dm.GetTotalFree() == 0) {
            Global.SlotsSoundMgr.playNormalBgm()
        }
    },

    //重写
    onMsgSpine: function (msg) {
        SlotsFacade.flowCtrl.onSpinMsg(msg);
    },

    //重写：显示bonus中奖
    OnSpinEnd: function () {
        SlotsFacade.flowCtrl.spinEnd();
    },

    //重写  重连进入房间
    ReconnectShow:function(){
        this.scheduleOnce(()=>{
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * 转换下标
     */
    transferIdx(idx) {
        idx = idx -1;
        let col = idx % this._col
        let row = this._row - Math.floor(idx/this._col) -1;
        return {col:col, row:row};
    },

    /**
     * 通过服务器idx获取全局坐标
     * @param {*} idx
     */
    getIdxGlobalPos(idx) {
        let idxInfo = this.transferIdx(idx);
        let reel = this._reels[idxInfo.col];
        let pos = reel.GetSymbolPosByRow(idxInfo.row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },

    /**
     * 播放scatter 中奖动画
     */
    async playTriggerAni(indexs) {
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 调用所有Symbol的StartMove 方法
     */
    startMoveAllSymbol() {
        for(let r of this._reels) {
            for(let s of r._symbols) {
                s.StartMove();
            }
        }
    },

    /**
     * 显示免费游戏标题
     * @param boo
     * @param type 普通免费0 超级免费1
     */
    showFreeTitle(boo, type) {
        let titleImg = cc.find("reels_frame/free_title", this.node).getComponent("ImgSwitchCmp");
        titleImg.node.active = boo;
        let frameTopImg = cc.find("reels_frame/up", this.node).getComponent("ImgSwitchCmp");
        if(boo) {
            titleImg.setIndex(type);
            frameTopImg.setIndex(1);
        }else {
            frameTopImg.setIndex(0);
        }
    },

    /**
     * 改变reel背景
     * @param isFree
     */
    changeReelsBg(isFree) {
        isFree = isFree || false;
        let index = isFree?1:0;
        for(let i=0; i<this._cfg.col; i++) {
            let reelBgImg = cc.find(`reels_bg/reel_bg${i+1}`, this.node).getComponent("ImgSwitchCmp");
            reelBgImg.setIndex(index);
        }
    }
});
